def replace_emoji(match):
    emoji = match.group(1)
    if emoji in svg_map:
        return svg_map[emoji]
    return match.group(0)

new_content = re.sub(r'<span class="emoji-blue">(.*?)</span>', replace_emoji, content)

with open('index.html', 'w', encoding='utf-8') as f:
    f.write(new_content)

